/**
 * The site's own text, one JSON file per language under `src/i18n/`. The documentation lives in
 * `Site/docs/<language>` and is generated by `scripts/generate-docs.mjs`.
 */
import en from "./i18n/en.json";
import ja from "./i18n/ja.json";
import zhCN from "./i18n/zh-CN.json";
import zhTW from "./i18n/zh-TW.json";

export const LANGUAGES = [
    {id: "en", label: "English"},
    {id: "ja", label: "日本語"},
    {id: "zh-CN", label: "简体中文"},
    {id: "zh-TW", label: "繁體中文"}
] as const;

export type Language = (typeof LANGUAGES)[number]["id"];

export const DEFAULT_LANGUAGE: Language = "en";

export interface Copy {
    nav: { home: string; scripts: string; docs: string };
    footer: string;
    home: {
        tagline: string;
        download: string;
        installScript: string;
        documentation: string;
        mainWindow: string;
        mainWindowAlt: string;
        whatTitle: string;
        whatText: string;
        popupTitle: string;
        popupText: string;
        popupCaption: string;
        popupAlt: string;
        featuresTitle: string;
        features: { name: string; text: string }[];
        installTitle: string;
        /** Text before the README link, the link label, and the text after it. */
        installBefore: string;
        readme: string;
        installAfter: string;
        platforms: { name: string; note: string }[];
    };
    scripts: {
        title: string;
        /** Uses `{scheme}` where the `checkurl://` code element goes. */
        subtitle: string;
        install: string;
        copy: string;
        copied: string;
    };
    docs: { scripting: string; libraries: string };
}

export const COPY: Record<Language, Copy> = {
    en,
    ja,
    "zh-CN": zhCN,
    "zh-TW": zhTW
};
